using System;
using System.Linq;
using System.Collections.Generic;
using SolidWorks.Interop.sldworks;

public partial class Cad {
    static bool IsConcentricReference(object reference){var face=reference as IFace2;if(face!=null)return ((ISurface)face.GetSurface()).IsCylinder();var edge=reference as IEdge;return edge!=null&&((ICurve)edge.GetCurve()).IsCircle();}
    Dictionary<string,object> MateReferenceGeometry(IModelDoc2 doc,object reference){return reference is IEdge?CircularMateGeometry(doc,(IEdge)reference):MateGeometry(doc,(IFace2)reference);}
    Dictionary<string,object> CircularMateGeometry(IModelDoc2 doc,IEdge edge,IComponent2 component=null,double[] pose=null,string cid=null,bool? fixedState=null){
        var curve=edge.GetCurve() as ICurve;if(curve==null||!curve.IsCircle())throw new CadFault("MATE_REFERENCE_TYPE_MISMATCH","仅支持圆形或圆弧边线，不将其他边线换成邻面。");
        var owner=((IEntity)edge).GetComponent() as IComponent2;if(owner==null||component!=null&&owner.Name2!=component.Name2)throw new CadFault("MATE_GEOMETRY_OWNER_UNAVAILABLE","圆边的装配实例归属无法核验。");
        var data=curve.CircleParams as double[];if(data==null||data.Length!=7||data.Any(v=>double.IsNaN(v)||double.IsInfinity(v))||data[6]<=0)throw new CadFault("MATE_GEOMETRY_UNSUPPORTED","原生圆参数无效。");
        pose=pose??(double[])owner.GetTotalTransform(false).ArrayData;var axis=ApplyPose(pose,data.Skip(3).Take(3).ToArray(),false);double length=Math.Sqrt(axis.Sum(v=>v*v));if(length<1e-12)throw new CadFault("MATE_GEOMETRY_UNSUPPORTED","圆轴线退化。");
        string persistent=Convert.ToBase64String((byte[])doc.Extension.GetPersistReference3(edge));int error;var restored=doc.Extension.GetObjectByPersistReference3(Convert.FromBase64String(persistent),out error) as IEdge;
        var actual=restored==null?null:((IEntity)restored).GetComponent() as IComponent2;if(error!=0||actual==null||actual.Name2!=owner.Name2)throw new CadFault("MATE_REFERENCE_STALE","圆边持久引用或实例归属往返核验失败。");
        var range=edge.GetCurveParams3() as ICurveParamData;double sweep=range==null?0:Math.Abs(range.UMaxValue-range.UMinValue);
        return new Dictionary<string,object>{{"full_circle",range!=null&&Math.Abs(sweep-2*Math.PI)<1e-6},{"edge_sweep_rad",sweep},{"edge_span_source",range==null?"unavailable":"native_edge_parameter_range"},{"entity_id",StableId("entity_",persistent)},{"component_id",cid??StableId("component_",Convert.ToBase64String((byte[])doc.Extension.GetPersistReference3(owner)))},{"instance",owner.Name2},{"kind","circular_edge"},{"reference_kind","edge"},{"curve_kind","native_circle_or_circular_arc"},{"axis_global",axis.Select(v=>v/length).ToArray()},{"reference_point_global_m",ApplyPose(pose,data.Take(3).ToArray(),true)},{"circle_radius_m",data[6]},{"fixed_component",fixedState??owner.IsFixed()},{"allowed_mate_types",new[]{"concentric"}},{"native_reference_roundtrip_verified",true},{"automatic_face_substitution",false}};
    }
    object ListCircularMateReferences(string id,string componentId,int limit,string cursor,bool compact,int edgeOffset,double budgetSeconds){
        if(limit<1||limit>50||edgeOffset<0||edgeOffset>0&&string.IsNullOrEmpty(componentId)||!GeometryScanBudget.ValidSeconds(budgetSeconds))throw new CadFault("INVALID_CIRCULAR_REFERENCE_OPTIONS","圆边查询须使用有效limit、预算和限定组件的edge_offset。");
        var timing=new OperationTiming();timing.Start("model_manifest");var m=GetUserModel(id);using(var scope=new Scope(this,m.Path,null)){
            string query=GeometryPageQuery("list_mate_references",m,componentId,"circular_edge",compact,edgeOffset,0,false,budgetSeconds);if(!string.IsNullOrEmpty(cursor))return ContinueGeometryPage(m,scope.Doc,query,cursor,limit,"list_mate_references",timing);
            timing.Start("component_inventory");InspectUserCore(m,scope.Doc);var cs=(((IAssemblyDoc)scope.Doc).GetComponents(true) as object[]??new object[0]).Cast<IComponent2>().OrderBy(c=>c.Name2,StringComparer.Ordinal).ToArray();if(cs.Length>500)throw new CadFault("COMPONENT_BUDGET_EXCEEDED","圆边查询最多500个顶层组件。");
            if(!string.IsNullOrEmpty(componentId)&&!cs.Any(c=>StableId("component_",Convert.ToBase64String((byte[])scope.Doc.Extension.GetPersistReference3(c)))==componentId))throw new CadFault("MATE_COMPONENT_UNSUPPORTED","圆边查询仅支持已登记的顶层零件。");
            var rows=new List<Dictionary<string,object>>();var references=new Dictionary<string,string>();var pending=new List<object>();var excluded=new List<object>();var skipped=new List<object>();var budget=NewGeometryBudget(budgetSeconds);int read=0;
            timing.Start("circular_edge_geometry");foreach(var c in cs){string cid=StableId("component_",Convert.ToBase64String((byte[])scope.Doc.Extension.GetPersistReference3(c)));if(!string.IsNullOrEmpty(componentId)&&cid!=componentId)continue;
                if(!budget.Continue()){pending.Add(new{component_id=cid,edge_offset=0,kind="circular_edge"});continue;}
                string reason=c.IsSuppressed()?"suppressed":c.IsSpeedPak?"speedpak":!c.GetPathName().EndsWith(".SLDPRT",StringComparison.OrdinalIgnoreCase)?"subassembly":null;if(reason!=null){excluded.Add(GeometryIssue(c,cid,reason));continue;}
                try{if(c.GetModelDoc2()==null)throw new CadFault("UNRESOLVED_COMPONENT","零件尚未解析，不能判断有无圆边。");object info;var solid=c.GetBodies3(0,out info) as object[]??new object[0];var sheet=c.GetBodies3(1,out info) as object[]??new object[0];var edges=solid.Concat(sheet).Cast<IBody2>().SelectMany(b=>(b.GetEdges() as object[]??new object[0]).Cast<IEdge>()).ToArray();
                    if(edgeOffset>edges.Length)throw new CadFault("EDGE_OFFSET_OUT_OF_RANGE","edge_offset超出当前原生边线列表，模型改变后须从0重查。");var pose=(double[])c.GetTotalTransform(false).ArrayData;bool fixedState=c.IsFixed();int accepted=0;
                    for(int i=edgeOffset;i<edges.Length;i++){if(!budget.Continue()||accepted>=128){pending.Add(new{component_id=cid,edge_offset=i,kind="circular_edge"});break;}read++;var curve=edges[i].GetCurve() as ICurve;if(curve==null||!curve.IsCircle())continue;var row=CircularMateGeometry(scope.Doc,edges[i],c,pose,cid,fixedState);row["native_edge_index"]=i;row["registration_status"]="registered_when_page_returned";row["registration_lifetime"]="checkpoint_restore_or_reference_state_change_requires_requery";rows.Add(row);references[(string)row["entity_id"]]=Convert.ToBase64String((byte[])scope.Doc.Extension.GetPersistReference3(edges[i]));accepted++;}
                }catch(CadFault error){if(error.Code=="EDGE_OFFSET_OUT_OF_RANGE")throw;skipped.Add(GeometryIssue(c,cid,error.Code,error));}catch(System.Runtime.InteropServices.COMException error){skipped.Add(GeometryIssue(c,cid,"CIRCULAR_EDGE_COM_FAILED",error));}
            }
            budget.Finish();timing.Start("pagination_signature");var queryState=CircularQueryState(m,scope.Doc);string guard=(string)queryState["signature"];timing.Finish();bool complete=pending.Count==0&&skipped.Count==0;
            var response=new Dictionary<string,object>{{"model_id",id},{"model_revision",m.Revision},{"total",rows.Count},{"kind","circular_edge"},{"geometry_complete",complete},{"scope_geometry_complete",complete},{"excluded_components",excluded.Take(20).ToArray()},{"excluded_component_count",excluded.Count},{"skipped_components",skipped.Take(20).ToArray()},{"skipped_component_count",skipped.Count},{"host_timings",timing.Export()},{"mate_context_complete",false},{"mate_context_status","not_scanned_use_recommendation_or_native_mate_inspection"},{"reference_capability",new{supported="top_level_circle_or_circular_arc_edge_concentric_only",unsupported=new[]{"noncircular_edge","sketch_segment","vertex"},automatic_substitution=false}},{"query_completion_status",complete?"complete_supported_geometry":"partial_pending_or_unresolved"},{"geometry_scan",new{geometry_scan_budget_s=budgetSeconds,read_edges=read,cooperative_budget_ms=budgetSeconds*1000,scan_budget_exhausted=budget.Exhausted,next_queries=pending.Take(5).ToArray(),pending_query_count=string.IsNullOrEmpty(componentId)?(int?)pending.Count:null,scope_pending_query_count=pending.Count,next_queries_truncated=pending.Count>5,client_must_retain_parent_pending_queue=true,component_completion_does_not_clear_siblings=true,native_call_cannot_be_interrupted=true}},{"claim","observed_circular_geometry_not_missing_mate_or_design_intent"}};
            response["reference_state_signature"]=guard;response["reference_state_evidence"]=queryState["state_evidence"];GeometryQueryScope.Apply(response,componentId,cs.Length,string.IsNullOrEmpty(componentId)?cs.Length:1,complete,pending.Count);return FreezeGeometryPage(m,query,guard,response,rows,references,limit);
        }
    }
}
